-- Pool's day — 약관 v1.0.3 시드 (자동 생성: scripts/gen-terms-seed.mjs)
--
-- ⚠️ 손으로 수정하지 말 것. termsContent.ts 갱신 후 생성기 재실행.
-- 자급자족·멱등: 0044 스키마 가드를 재포함하므로 0044 적용 여부와 무관하게 안전.
-- content jsonb = 전체 TermsMeta({title, version, effectiveDate, sections}).
--
-- v1.0.3: Firebase Analytics 제거 + Apple 로그인 정식 반영(처리방침·수집동의·
--   이용약관 본문 변경). 위치·마케팅은 본문 변경 없으나 릴리스 버전 동기화.

-- ① 스키마 가드(0044와 동일·멱등) ------------------------------------------
create table if not exists public.terms (
  id               uuid primary key default gen_random_uuid(),
  type             text not null check (type in
                     ('service','privacy_consent','privacy_policy',
                      'location','marketing')),
  version          text not null,
  effective_date   date not null,
  content          jsonb not null,
  is_required      boolean not null default true,
  requires_consent boolean not null default true,
  is_active        boolean not null default false,
  created_at       timestamptz not null default now(),
  unique (type, version)
);
create unique index if not exists terms_one_active_per_type
  on public.terms (type) where is_active;
alter table public.terms enable row level security;
drop policy if exists terms_read_all on public.terms;
create policy terms_read_all on public.terms for select using (true);

-- ② v1.0.3 시드 — type별 upsert + is_active 교체 -------------------------

-- service
update public.terms set is_active=false where type='service' and version<>'1.0.3';
insert into public.terms (type, version, effective_date, content, is_required, requires_consent, is_active)
values ('service', '1.0.3', '2026-05-28', $tjson${"title":"서비스 이용약관","version":"v1.0.3","effectiveDate":"2026년 5월 28일","sections":[{"title":"들어가며","body":"안녕하세요. Pool's day(풀스데이)에 오신 것을 환영합니다. 아래 약관은 조금 딱딱하게 느껴질 수 있지만, 이용자와 서비스가 서로 약속하는 내용을 분명히 해두려는 것이니 한 번 읽어 주시면 좋겠습니다. 오늘도 좋은 물에서 만나길 바랍니다."},{"title":"제1조 (목적)","body":"이 약관은 CRIPO(이하 \"회사\")가 제공하는 모바일 애플리케이션 \"Pool's day\"(이하 \"서비스\")의 이용과 관련하여 회사와 이용자 간의 권리, 의무 및 책임사항, 서비스 이용조건 및 절차 등 기본적인 사항을 규정함을 목적으로 합니다."},{"title":"제2조 (정의)","body":"이 약관에서 사용하는 용어의 정의는 다음과 같습니다.\n\n· \"서비스\"란 회사가 제공하는, 자유수영이 가능한 수영장을 지도에서 찾고 자유수영 시간표를 열람하며 개인 수영 일정을 관리하는 모바일 애플리케이션 및 이에 부수하는 일체의 서비스를 말합니다.\n· \"이용자\"란 이 약관에 따라 회사가 제공하는 서비스를 이용하는 회원 및 비회원을 말합니다.\n· \"비회원\"이란 회원 가입 없이 서비스의 공개 기능(지도 탐색, 수영장 정보 조회, 자유수영 시간표 열람, 공지사항 열람, 수영장 등록·수정 제보)을 이용하는 자를 말합니다.\n· \"회원\"이란 소셜 로그인을 통해 본인을 확인하고 이 약관에 동의하여 프로필을 생성한 후 서비스의 개인 기능을 이용하는 자를 말합니다.\n· \"콘텐츠\"란 이용자가 서비스를 통해 입력·등록하는 프로필 정보, 닉네임, 프로필 사진, 수영장 등록·수정 제보, 자유수영 시간표 제보 등 일체의 정보를 말합니다.\n· \"친구코드\"란 회원 식별 및 친구 추가, 알림 수신을 위하여 회원에게 자동으로 부여되는 6자리 식별 문자열을 말합니다.\n\n이 약관에서 정하지 아니한 용어의 의미는 관계 법령 및 일반 관례에 따릅니다."},{"title":"제3조 (약관의 명시와 개정)","body":"회사는 이 약관의 내용을 이용자가 쉽게 알 수 있도록 서비스 내 설정 화면 등에 게시합니다.\n\n회사는 「약관의 규제에 관한 법률」, 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」, 「개인정보 보호법」, 「위치정보의 보호 및 이용 등에 관한 법률」 등 관련 법령을 위배하지 않는 범위에서 이 약관을 개정할 수 있습니다.\n\n회사가 약관을 개정할 경우에는 적용일자 및 개정사유를 명시하여 그 적용일자 7일 전부터 서비스 내 공지사항을 통하여 공지합니다. 다만, 이용자에게 불리하거나 중대한 변경의 경우에는 최소 30일 전부터 공지하고, 가능한 경우 별도의 전자적 수단으로 함께 통지합니다.\n\n회사가 전항에 따라 개정약관을 공지하면서 이용자에게 적용일 전까지 거부의사를 표시하지 않으면 동의한 것으로 본다는 뜻을 명확히 고지하였음에도 이용자가 명시적으로 거부의사를 표시하지 아니한 경우, 이용자가 개정약관에 동의한 것으로 봅니다. 이용자가 개정약관에 동의하지 않는 경우 이용계약을 해지(회원 탈퇴)할 수 있습니다."},{"title":"제4조 (약관 외 준칙)","body":"이 약관에서 정하지 아니한 사항과 이 약관의 해석에 관하여는 관계 법령 또는 회사가 정한 개별 서비스의 이용안내, 운영정책 및 관례에 따릅니다.\n\n회사는 개인정보 처리방침, 개인정보 수집·이용 동의서, 위치기반서비스 이용약관, 마케팅 정보 수신 동의서를 이 약관과 별도로 두며, 해당 문서가 정하는 사항은 그 문서에 따릅니다."},{"title":"제5조 (이용계약의 체결)","body":"이용계약은 이용자가 되고자 하는 자가 소셜 로그인(Google 또는 Kakao)을 통해 본인을 확인하고, 이 약관 및 회원 가입 시 제시되는 필수 동의 항목에 동의한 후 프로필을 생성함으로써 체결됩니다.\n\n회원 가입 시 필수 동의 항목은 다음과 같습니다.\n\n· 본인이 만 14세 이상임을 확인\n· 서비스 이용약관 동의\n· 개인정보 수집·이용 동의\n· 위치기반서비스 이용약관 동의\n\n마케팅 정보 수신 동의는 선택 사항이며, 동의하지 않아도 서비스 이용에 제한이 없습니다.\n\n회사는 만 14세 미만 아동의 가입을 받지 않으며, 가입 시 만 14세 이상임을 확인합니다. 만 14세 미만임이 확인된 경우 회사는 해당 계정의 이용을 제한하거나 이용계약을 해지할 수 있습니다.\n\n회사는 다음 각 호에 해당하는 경우 이용계약 체결을 거부하거나 사후에 이용계약을 해지할 수 있습니다.\n\n· 타인의 명의나 소셜 계정을 도용한 경우\n· 만 14세 미만인 경우\n· 이 약관에 의하여 이전에 이용제한 또는 이용계약 해지된 적이 있는 경우\n· 부정한 용도 또는 관련 법령에 위반하여 서비스를 이용하려는 경우"},{"title":"제6조 (회원정보의 관리 및 저장 방식)","body":"서비스의 특성상 회원의 프로필 정보(닉네임, 성별, 생년월일, 수영경력, 영법, 자기소개, 자격증, 기록, 레슨 정보, 항목별 공개범위 설정, 자주 가는 수영장, 내 수영 일정 등)는 원칙적으로 회원 본인의 기기 내부에만 저장되며 회사 서버로 전송되지 않습니다. 다만 닉네임 중복 방지를 위한 닉네임 문자열, 프로필 사진, 알림 이력, 제보 데이터는 회사 서버에 저장됩니다. 자세한 내용은 개인정보 처리방침에서 안내합니다.\n\n회원은 본인의 정보를 항상 정확하게 유지하여야 하며, 기기 분실·변경 또는 앱 삭제 시 기기에만 저장된 정보는 복구되지 않을 수 있습니다.\n\n회원은 친구코드 및 소셜 로그인 계정을 직접 관리할 책임이 있으며, 이를 제3자가 이용하도록 하여서는 안 됩니다."},{"title":"제7조 (서비스의 제공)","body":"회사는 이용자에게 다음과 같은 서비스를 제공합니다.\n\n[비회원도 이용할 수 있는 기능]\n· 지도에서 자유수영 가능 수영장 탐색(위치 기반)\n· 수영장 정보 조회(시설, 요금, 전화, 주소, 레인 수, 길이, 수심 등)\n· 자유수영 시간표 열람(요일별, 시즌별)\n· 수영장 등록 및 정보 수정 제보\n· 공지사항 열람\n\n[회원만 이용할 수 있는 기능]\n· 내 수영 일정 등록 및 관리(달력)\n· 친구 등록 및 관리(닉네임 또는 친구코드 검색)\n· 일정에 친구 초대\n· 자주 가는 수영장 관리\n· 프로필 관리 및 항목별 공개범위 설정\n· 인앱 알림 및 OS 푸시 알림 수신 (OS 푸시 알림은 기기 운영체제의 알림 권한을 허용한 경우에 한함)\n\n[향후 제공 예정 기능]\n· 수영 번개모임 및 정기모임\n· 프리미엄 구독 등 유료 서비스(검토 중이며 도입 여부는 미확정)\n\n회사는 향후 제공 예정 기능을 도입할 경우 이 약관 또는 별도 문서를 통해 사전에 안내합니다.\n\n회사가 제공하는 수영장 정보 및 자유수영 시간표는 운영자 검토를 거쳐 등록되나, 각 수영장의 실제 운영 사정에 따라 변경될 수 있으므로 회사는 그 정확성, 완전성 또는 최신성을 보장하지 않습니다. 이용자는 방문 전 해당 수영장에 직접 확인할 것을 권장합니다."},{"title":"제8조 (서비스의 변경 및 중단)","body":"회사는 서비스의 내용, 운영상·기술상 사항을 변경할 수 있으며, 변경 시 그 내용을 사전에 공지합니다. 다만 긴급하거나 중대한 사유가 있는 경우 사후에 공지할 수 있습니다.\n\n회사는 다음 각 호의 경우 서비스의 전부 또는 일부 제공을 일시적으로 중단할 수 있습니다.\n\n· 시스템 점검, 보수, 교체 또는 고장, 통신 두절 등의 경우\n· 천재지변, 국가비상사태, 정전 등 불가항력적 사유가 있는 경우\n· 서비스 제공을 위해 이용하는 외부 시스템(클라우드 인프라, 인증 제공자, 지도 제공자 등)의 장애가 있는 경우\n\n서비스가 무료로 제공되는 점을 고려하여, 회사는 사전 고지 후 서비스의 전부 또는 일부를 종료할 수 있습니다."},{"title":"제9조 (정보의 제공 및 광고)","body":"회사는 서비스 운영에 필요한 공지사항, 안내사항 등을 서비스 내 공지 또는 인앱 알림 등의 방법으로 이용자에게 제공할 수 있습니다.\n\n광고성 정보(이벤트, 혜택 안내 등)의 전송은 마케팅 정보 수신 동의서에 별도로 동의한 회원에 한하여 이루어집니다."},{"title":"제10조 (이용자의 의무)","body":"이용자는 다음 행위를 하여서는 안 됩니다.\n\n· 타인의 정보를 도용하거나 허위 사실을 등록·제보하는 행위\n· 회사 또는 제3자의 지식재산권, 명예, 기타 권리를 침해하는 행위\n· 욕설, 비방, 차별, 음란, 폭력적 표현 등 타인에게 불쾌감을 주거나 공서양속에 반하는 내용을 닉네임, 자기소개, 제보 등에 사용하는 행위\n· 자동화된 수단을 이용하여 서비스에 비정상적으로 접근하거나 부하를 유발하는 행위\n· 서비스의 정상적 운영을 방해하거나 안정성을 해치는 행위\n· 관련 법령을 위반하는 행위"},{"title":"제11조 (콘텐츠 및 제보의 처리)","body":"이용자가 서비스에 등록·제보한 콘텐츠의 저작권은 해당 이용자에게 귀속됩니다.\n\n다만 이용자는 수영장 등록·수정 제보 및 자유수영 시간표 제보 등 서비스 운영을 위해 제공한 콘텐츠에 대하여, 회사가 이를 검토·수정·보완하여 수영장 정보 및 시간표로 등록·표시·배포할 수 있도록 비독점적이고 무상이며 전 세계적인 사용권을 회사에 부여합니다. 이 사용권은 서비스 운영 목적의 범위 내에서만 행사됩니다.\n\n제보 콘텐츠는 운영자 검토를 거치며, 회사는 제보의 정확성 검증, 중복 또는 부적절한 내용의 미게재, 수정 후 게재 여부를 결정할 수 있습니다.\n\n회사는 이용자의 콘텐츠가 관련 법령 또는 이 약관에 위반된다고 판단되는 경우 사전 통지 없이 해당 콘텐츠를 게재하지 않거나 삭제할 수 있습니다."},{"title":"제12조 (이용제한 및 이용계약의 해지)","body":"이용자는 언제든지 서비스 내 설정 메뉴의 \"회원 탈퇴\" 절차(3단계 확인)를 통하여 이용계약을 해지할 수 있습니다.\n\n회원 탈퇴 시 데이터 처리는 다음과 같습니다.\n\n· 즉시 삭제: 기기에 저장된 정보(프로필, 일정, 즐겨찾기, 설정 등)는 탈퇴 즉시 해당 기기에서 삭제되며, 서비스 로그아웃 및 소셜 로그아웃이 함께 처리됩니다. 서버에 저장된 프로필 사진도 즉시 삭제됩니다.\n· 즉시 파기: 닉네임 선점 기록 및 알림 이력도 회원 탈퇴 시 지체 없이 파기됩니다.\n· 익명화 후 보존: 수영장·시간표 제보 데이터는 수영장 정보의 공익적 성격을 고려하여 개인 식별이 불가능하도록 익명화한 후 운영·통계 목적으로 보존될 수 있습니다.\n· 영구 보존: 없습니다.\n\n회사는 회원 탈퇴 즉시 서버 측 계정 식별자(인증 정보 포함), 프로필 본체, 닉네임 선점 기록, 알림 이력, 후원 응원 메시지, 스토리지의 프로필 사진을 자동으로 영구 삭제합니다. 후원 입금 식별 정보는 「국세기본법」 등 관련 법령에 따른 회계·세무 기록 보존 의무 기간 동안 보존된 뒤 파기됩니다.\n\n회사는 이용자가 이 약관 또는 관련 법령을 위반한 경우 사전 통지 후(긴급한 경우 사후 통지) 서비스 이용을 제한하거나 이용계약을 해지할 수 있습니다."},{"title":"제13조 (책임의 한계 및 면책)","body":"서비스는 무료로 제공됩니다. 회사는 천재지변, 불가항력, 이용자의 귀책사유, 또는 회사가 제공하는 외부 시스템(클라우드 인프라, 인증 제공자, 지도 제공자 등)의 장애로 인하여 서비스를 제공할 수 없는 경우 그에 대한 책임을 지지 않습니다.\n\n회사는 수영장 정보, 자유수영 시간표, 요금, 운영 여부 등 운영자 검토를 거쳐 제공되는 정보의 정확성·완전성·최신성을 보장하지 않으며, 이용자가 해당 정보를 신뢰하여 입은 손해에 대하여 회사의 고의 또는 중대한 과실이 없는 한 책임을 지지 않습니다.\n\n회사는 이용자 상호 간 또는 이용자와 제3자 간에 서비스를 매개로 발생한 분쟁(친구 관계, 일정 동행 등)에 대하여 개입할 의무가 없으며, 그로 인한 손해에 대하여 책임을 지지 않습니다.\n\n이용자가 서비스에 등록·제보한 콘텐츠의 내용에 대한 책임은 해당 이용자에게 있습니다."},{"title":"제14조 (유료 서비스)","body":"현재 서비스에는 결제, 구독, 인앱구매, 유료 광고 등 유료 항목이 없습니다.\n\n회사가 향후 프리미엄 구독 등 유료 서비스를 도입하는 경우, 결제 방법, 청약철회 및 환불, 과오금 처리 등에 관한 구체적 사항을 별도의 약관 또는 이용안내로 정하여 사전에 고지하며, 도입 전까지 이용자에게 유료 서비스 이용을 강제하지 않습니다."},{"title":"제15조 (후원금)","body":"회사는 서비스 운영을 응원하고자 하는 이용자가 자발적으로 후원할 수 있는 안내(은행 계좌 정보 등)를 앱 내에 제공할 수 있습니다.\n\n후원은 다음과 같이 처리됩니다.\n\n1. 후원은 결제, 구독, 유료 서비스 이용이 아니며, 이용자가 자발적으로 송금하는 기증(증여)의 성격을 가집니다. 따라서 송금된 후원금은 환불·반환되지 않습니다.\n2. 회사는 후원금을 서비스 운영(서버·인프라 비용, 사진·이미지 자원, 도메인, 외부 API 사용료 등)에 사용합니다. 별도의 회계 보고 의무는 부담하지 않으나, 이용자에게 신의에 부합하게 사용합니다.\n3. 회사는 후원자가 본인 식별을 원할 경우, 송금 시 입력한 입금자명(또는 닉네임)을 통해 앱 내 후원자에게 인앱 알림으로 감사 인사를 전달할 수 있습니다. 입금자명이 회원의 닉네임과 일치하지 않는 등 매칭이 불가능한 경우, 감사 인사가 전달되지 않을 수 있습니다.\n4. 회사는 입금 확인 후 후원자를 응원 목록에 자동으로 등록하며, 등록 시 기본 응원 문구가 함께 표시됩니다. 등록된 항목에는 후원자의 닉네임이 함께 표시되어 다른 이용자에게 공개될 수 있습니다. 이용자는 본인 항목의 응원 문구를 자유롭게 수정하거나 비공개로 전환할 수 있으며, 비공개로 전환된 항목은 본인 포함 모든 이용자에게 표시되지 않습니다(서비스 내부 이력은 보존됩니다).\n5. 후원 안내·후원자 표시는 영리 목적의 광고가 아니며, 송금 과정에서의 사기 등은 회사의 책임 범위에 포함되지 않습니다. 이용자는 입금 전 계좌 정보·예금주를 반드시 확인해야 합니다."},{"title":"제16조 (준거법 및 재판관할)","body":"이 약관 및 서비스 이용과 관련하여 회사와 이용자 간에 발생한 분쟁에 관하여는 대한민국 법을 준거법으로 합니다.\n\n회사와 이용자 간에 발생한 분쟁에 관한 소송은 「민사소송법」에 따른 관할 법원을 제1심 관할 법원으로 합니다.\n\n회사와 이용자는 분쟁 해결을 위하여 성실히 협의하며, 협의가 이루어지지 않을 경우 「소비자기본법」에 따른 소비자분쟁조정위원회 등 관련 분쟁조정기구의 조정을 신청할 수 있습니다."},{"title":"사업자 정보","body":"· 상호: CRIPO\n· 대표자: 김은호\n· 사업자등록번호: 379-13-02772\n· 사업장 주소: 경기도 화성시 병점구 효행로 1068, 604호\n· 이메일: cripo2357@gmail.com"},{"title":"부칙","body":"이 약관은 2026년 5월 28일부터 시행합니다.\n\n물에서 또 만나요. — Pool's day 드림"}]}$tjson$::jsonb, true, true, true)
on conflict (type, version) do update set
  content=excluded.content, effective_date=excluded.effective_date,
  is_required=excluded.is_required, requires_consent=excluded.requires_consent, is_active=true;

-- privacy_consent
update public.terms set is_active=false where type='privacy_consent' and version<>'1.0.3';
insert into public.terms (type, version, effective_date, content, is_required, requires_consent, is_active)
values ('privacy_consent', '1.0.3', '2026-05-28', $tjson${"title":"개인정보 수집·이용 동의","version":"v1.0.3","effectiveDate":"2026년 5월 28일","sections":[{"title":"들어가며","body":"안녕하세요, 수영 좋아하는 분들의 동네 친구 Pool's day(풀스데이)입니다. 아래는 가입할 때 받는 개인정보 수집·이용 동의 안내예요. 어떤 정보를, 왜, 어디에 두는지 솔직하게 적어 두었으니 가볍게 한 번 확인해 주세요.\n\nCRIPO(이하 \"회사\")는 「개인정보 보호법」 제15조에 따라 Pool's Day(풀스데이) 서비스 제공을 위하여 아래와 같이 개인정보를 수집·이용하고자 하며, 그 내용을 충분히 안내해 드립니다. 아래 내용을 확인하신 후 동의 여부를 선택하여 주시기 바랍니다.\n\n본 동의서는 회원 가입 시 필수 동의 항목 중 \"개인정보 수집·이용 동의\"에 해당합니다."},{"title":"1. 수집·이용 목적","body":"회사는 다음의 목적으로 개인정보를 수집·이용합니다.\n\n· 회원 식별 및 본인 확인, 이용계약의 체결·유지·이행\n· 자유수영 수영장 탐색, 시간표 열람, 내 수영 일정 관리, 친구 및 일정 초대 등 서비스 기능 제공\n· 닉네임 중복 방지 및 부정 이용 방지\n· 수영장 등록·수정 제보 및 자유수영 시간표 제보의 검토·운영\n· 인앱 알림 등 서비스 운영에 필요한 안내 제공\n· 고객 문의 응대 및 분쟁 처리"},{"title":"2. 수집하는 개인정보 항목","body":"서비스의 특성상 회원의 프로필 정보 대부분은 회원 본인의 기기 내부에만 저장되며 회사 서버로 전송되지 않습니다. 항목별 저장 위치를 함께 안내합니다.\n\n[필수 항목]\n· 소셜 로그인 신원(Google, Apple 또는 Kakao 제공자 식별자, 인증 식별자) — 회사 인증 시스템에 저장\n· 이메일(소셜 로그인 제공) — 회사 인증 시스템에만 보관(별도 항목으로 복사하지 않음)\n· 닉네임(2자 이상 6자 이하) — 기기에 저장되며, 중복 방지를 위해 닉네임 문자열만 서버에 저장\n· 성별 — 기기에만 저장\n· 생년월일 — 기기에만 저장(만 14세 이상 확인 및 프로필 용도)\n· 친구코드(6자리, 자동 생성) — 기기에 저장되며, 알림 수신 식별을 위해 서버에 함께 저장\n\n[선택 항목]\n· 수영경력, 영법 — 기기에만 저장\n· 프로필 사진 — 회사 스토리지(소유자 폴더)에 저장\n· 자기소개, 자격증, 기록, 레슨 정보, 항목별 공개범위 설정, 자주 가는 수영장, 내 수영 일정 — 기기에만 저장\n· 수영장·시간표 제보 내용 및 제보자 연락처(입력 시) — 회사 서버에 저장(운영자 검토용)\n· 알림 이력(초대 전송·거절 등 행위 기록, 상대 표시명·수영장·시간 포함) — 회사 서버에 저장\n· 후원 응원 메시지(회사가 후원자에게 자동으로 등록한 기본 문구. 이용자가 수정 가능, 최대 300자) — 회사 서버에 저장. 후원자 닉네임과 함께 공개 표시되며, 이용자가 비공개로 전환하면 본인 포함 모두에게 미표시(이력은 보존).\n· 후원 입금 식별 정보(입금자명, 입금 금액, 입금 일시) — 회사 서버에 저장. 후원자 식별 및 인앱 감사 인사 발송 목적으로만 이용되며, 회사 운영자에게만 접근이 허용되고 다른 이용자에게는 공개되지 않습니다.\n\n회사는 광고식별자(ADID/IDFA) 매칭, 맞춤형 광고 목적의 행태정보 수집을 하지 않습니다. 다만 서비스의 안정적 운영과 품질 개선을 위하여 다음 운영 인프라 데이터가 처리됩니다.\n\n· 크래시 및 에러 리포팅 (Sentry — Functional Software Inc., 미국): 앱 비정상 종료 또는 처리되지 않은 오류 발생 시 스택 트레이스, 에러 메시지, 발생 환경(앱 버전, 운영체제 종류). 자동 IP 수집은 비활성화되어 있으며, 로그인 사용자의 경우 식별자로 친구 코드 (6자 무작위 문자열)만 함께 전송됩니다.\n\nOS 푸시 알림 발송을 위하여 푸시 토큰(Android의 Firebase Cloud Messaging 또는 iOS의 Apple Push Notification Service가 발급하는 기기별 식별자)이 수집·저장됩니다. 푸시 토큰은 푸시 알림 발송 목적으로만 이용되며, 회원 탈퇴 또는 OS 푸시 권한 거부 시 즉시 폐기됩니다.\n\n기기 위치정보의 일시적 이용에 관하여는 위치기반서비스 이용약관에서 별도로 안내합니다.\n\n민감정보(건강, 사상, 정치적 견해, 생체정보 등) 및 고유식별정보(주민등록번호, 여권번호, 운전면허번호, 외국인등록번호)는 수집하지 않습니다."},{"title":"3. 보유·이용 기간","body":"· 소셜 로그인 신원, 이메일, 닉네임 문자열, 친구코드: 회원 탈퇴 시까지 보유하며, 탈퇴 시 지체 없이 파기합니다.\n· 기기에만 저장되는 정보(프로필, 일정, 즐겨찾기, 설정 등): 회원 탈퇴 또는 앱 삭제 시 해당 기기에서 삭제됩니다.\n· 프로필 사진: 회원 탈퇴 시 즉시 삭제합니다.\n· 닉네임 선점 기록 및 알림 이력: 회원 탈퇴 시 지체 없이 파기합니다.\n· 수영장·시간표 제보 데이터: 수영장 정보의 공익적 성격을 고려하여 개인 식별이 불가능하도록 익명화한 후 운영·통계 목적으로 보존될 수 있습니다.\n· 후원 응원 메시지: 회원 탈퇴 시 즉시 삭제합니다. 이용자가 비공개로 전환한 경우 본인 포함 화면에는 표시되지 않으나 회사 서버에는 이력이 보존됩니다.\n· 후원 입금 식별 정보: 「국세기본법」 등 관련 법령에 따른 회계·세무 기록 보존 의무가 적용될 수 있으며, 해당 법령에서 정한 기간(통상 5년)까지 보존 후 파기합니다.\n· 영구 보존되는 개인정보는 없습니다."},{"title":"4. 동의를 거부할 권리 및 거부 시 불이익","body":"이용자는 위 개인정보 수집·이용에 대한 동의를 거부할 권리가 있습니다.\n\n다만 필수 항목은 서비스의 회원 가입 및 개인 기능 제공에 반드시 필요한 정보이므로, 동의를 거부하실 경우 회원 가입 및 개인 기능 이용이 제한됩니다. 비회원으로 이용 가능한 공개 기능(지도 탐색, 수영장 정보 조회, 시간표 열람, 공지사항 열람, 제보)은 동의 없이도 이용할 수 있습니다.\n\n선택 항목에 대한 동의를 거부하시더라도 회원 가입 및 기본적인 서비스 이용에는 제한이 없습니다."},{"title":"5. 처리위탁 및 국외 처리 안내","body":"회사는 서비스 제공을 위하여 일부 업무를 외부 전문 업체에 위탁하고 있으며, 회원 데이터가 저장되는 인프라는 국내(서울 리전)에 위치합니다. 다만 다음의 경우 국외(미국 등) 위탁이 발생할 수 있습니다.\n\n· Google 또는 Apple 계정으로 로그인하는 경우: Google LLC(미국) 또는 Apple Inc.(미국)를 통한 본인 인증\n· OS 푸시 알림 발송: Google LLC(Firebase Cloud Messaging, 미국) 또는 Apple Inc.(APNs, 미국)\n· 크래시 및 에러 리포팅: Functional Software Inc.(Sentry, 미국)\n\n위탁 업체 및 처리 국가에 관한 자세한 사항은 개인정보 처리방침에서 안내합니다."},{"title":"6. 만 14세 미만 아동에 관한 사항","body":"회사는 만 14세 미만 아동의 회원 가입을 받지 않습니다. 회원 가입 시 만 14세 이상임을 확인하며, 만 14세 미만 아동의 개인정보는 수집하지 않습니다."},{"title":"동의","body":"본인은 위 개인정보 수집·이용에 관한 안내를 충분히 읽고 이해하였으며, 이에 동의합니다.\n\n(필수) 개인정보 수집·이용에 동의합니다."},{"title":"부칙","body":"이 동의서는 2026년 5월 28일부터 시행합니다."}]}$tjson$::jsonb, true, true, true)
on conflict (type, version) do update set
  content=excluded.content, effective_date=excluded.effective_date,
  is_required=excluded.is_required, requires_consent=excluded.requires_consent, is_active=true;

-- privacy_policy
update public.terms set is_active=false where type='privacy_policy' and version<>'1.0.3';
insert into public.terms (type, version, effective_date, content, is_required, requires_consent, is_active)
values ('privacy_policy', '1.0.3', '2026-05-28', $tjson${"title":"개인정보 처리방침","version":"v1.0.3","effectiveDate":"2026년 5월 28일","sections":[{"title":"들어가며","body":"안녕하세요, Pool's day(풀스데이)입니다. 이 문서는 회사가 여러분의 개인정보를 어떻게 다루는지 숨김없이 알려드리는 안내문이에요. 조항이 조금 길지만 핵심은 단순합니다. 대부분의 정보는 여러분 기기 안에만 있고 회사 서버로 보내지 않으니, 편한 마음으로 천천히 살펴봐 주세요.\n\nCRIPO(이하 \"회사\")는 「개인정보 보호법」 제30조에 따라 정보주체의 개인정보를 보호하고 이와 관련한 고충을 신속하고 원활하게 처리할 수 있도록 하기 위하여 다음과 같이 개인정보 처리방침을 수립·공개합니다.\n\n본 처리방침은 이용자에게 회사의 개인정보 처리 현황을 알려드리는 고지 문서이며, 회원 가입 시 동의 대상 문서가 아닙니다.\n\n회사가 운영하는 Pool's day(풀스데이) 서비스는 이용자의 개인정보 대부분을 회사 서버가 아닌 이용자 본인의 기기 내부에만 저장한다는 점에서 일반적인 서비스와 구별됩니다. 본 처리방침은 그 처리 구조를 사실 그대로 안내합니다."},{"title":"제1조 (개인정보의 처리 목적)","body":"회사는 다음의 목적을 위하여 개인정보를 처리합니다. 처리하는 개인정보는 다음 목적 이외의 용도로는 이용되지 않으며, 이용 목적이 변경되는 경우에는 「개인정보 보호법」 제18조에 따라 별도의 동의를 받는 등 필요한 조치를 이행합니다.\n\n· 회원 관리: 소셜 로그인 기반 회원 식별 및 본인 확인, 이용계약의 체결·유지·이행, 닉네임 중복 방지, 부정 이용 방지\n· 서비스 제공: 자유수영 수영장 탐색, 자유수영 시간표 열람, 내 수영 일정 관리, 친구 등록 및 일정 초대, 인앱 알림 제공\n· 사용자 기여 처리: 수영장 등록·수정 제보 및 자유수영 시간표 제보의 검토·반영\n· 고충 처리: 이용자 문의 응대, 분쟁 처리 및 피해 구제"},{"title":"제2조 (처리하는 개인정보의 항목)","body":"회사는 다음의 개인정보 항목을 처리합니다. 항목별 저장 위치를 함께 안내합니다.\n\n[필수 항목]\n· 소셜 로그인 신원(Google, Apple 또는 Kakao 제공자 식별자, 인증 식별자): 회사 인증 시스템에 저장 — 계정 식별 및 로그인\n· 이메일(소셜 로그인 제공): 회사 인증 시스템에만 보관 — 계정 식별\n· 닉네임(2자 이상 6자 이하): 기기에 저장, 중복 방지를 위해 닉네임 문자열만 서버에 저장 — 표시명, 친구 검색\n· 성별: 기기에만 저장 — 프로필, 기본 아바타\n· 생년월일: 기기에만 저장 — 만 14세 이상 확인, 프로필\n· 친구코드(6자리, 자동 생성): 기기에 저장, 알림 수신 식별을 위해 서버에 함께 저장 — 친구 추가, 알림 수신\n\n[선택 항목]\n· 수영경력, 영법: 기기에만 저장 — 프로필\n· 프로필 사진: 회사 스토리지(소유자 폴더)에 저장 — 아바타\n· 자기소개, 자격증, 기록, 레슨 정보, 항목별 공개범위 설정, 자주 가는 수영장, 내 수영 일정: 기기에만 저장 — 프로필 및 일정 관리\n· 수영장·시간표 제보 내용 및 제보자 연락처(입력 시): 회사 서버에 저장 — 운영자 검토\n· 알림 이력(초대 전송·거절 등 행위 기록, 상대 표시명·수영장·시간 포함): 회사 서버에 저장 — 알림 기록\n\n[자동 수집 항목]\n회사는 광고식별자(ADID/IDFA) 매칭이나 맞춤형 광고 목적의 행태정보 수집을 하지 않으며, 분석·광고 목적의 외부 도구를 사용하지 않습니다. 다만 서비스의 안정적 운영과 품질 개선을 위하여 다음 운영 인프라가 사용됩니다.\n\n· 크래시 및 에러 리포팅: Sentry(Functional Software Inc. 운영, 미국)가 앱 비정상 종료 또는 처리되지 않은 오류 발생 시 스택 트레이스, 에러 메시지, 발생 환경(앱 버전, 운영체제 종류)을 수집합니다. 자동 IP 수집은 비활성화되어 있으며, 로그인 사용자의 경우 식별자로 친구 코드(6자 무작위 문자열)만 함께 전송됩니다. 리포트는 서비스 안정성 개선 목적으로만 이용됩니다.\n\n· 푸시 토큰: OS 푸시 알림 발송을 위해 운영체제(Android의 Firebase Cloud Messaging 또는 iOS의 Apple Push Notification Service)가 발급하는 기기별 식별자를 수집·저장합니다. 푸시 토큰은 회원 탈퇴 시 또는 OS 푸시 권한이 거부된 시점에 즉시 폐기되며, 90일 이상 미사용 토큰은 자동 정리됩니다. 푸시 알림 수신을 원하지 않으시는 경우 기기 운영체제의 알림 권한 설정에서 본 서비스의 알림 권한을 해제하실 수 있습니다.\n· 기기 위치정보: 서비스 제공 시점에 일시적으로 이용될 수 있으며, 이에 관하여는 제8조 및 위치기반서비스 이용약관에서 별도로 안내합니다.\n\n[민감정보 및 고유식별정보]\n회사는 민감정보(건강, 사상, 정치적 견해, 노동조합 가입, 생체정보, 범죄경력 등) 및 고유식별정보(주민등록번호, 여권번호, 운전면허번호, 외국인등록번호)를 수집하지 않습니다."},{"title":"제3조 (개인정보의 처리 및 보유 기간)","body":"회사는 법령에 따른 보유·이용 기간 또는 정보주체로부터 동의받은 보유·이용 기간 내에서 개인정보를 처리·보유하며, 다음과 같이 처리합니다.\n\n· 소셜 로그인 신원, 이메일, 닉네임 문자열, 친구코드: 회원 탈퇴 시까지 보유하며 탈퇴 시 지체 없이 파기\n· 기기에만 저장되는 정보: 회원 탈퇴 또는 앱 삭제 시 해당 기기에서 삭제\n· 프로필 사진: 회원 탈퇴 시 즉시 삭제\n· 푸시 토큰: 회원 탈퇴, OS 푸시 권한 거부 또는 90일 이상 미사용 시 즉시 폐기\n· 닉네임 선점 기록, 알림 이력: 회원 탈퇴 시 지체 없이 파기\n· 수영장·시간표 제보 데이터: 수영장 정보의 공익적 성격을 고려하여 익명화한 후 운영·통계 목적으로 보존될 수 있음\n\n본 서비스는 결제·거래가 없는 무료 서비스로서, 「전자상거래 등에서의 소비자보호에 관한 법률」 등에 따른 거래기록 보존 의무가 적용되지 않습니다. 영구 보존되는 개인정보는 없습니다."},{"title":"제4조 (개인정보의 제3자 제공)","body":"회사는 정보주체의 개인정보를 제1조에서 명시한 범위 내에서만 처리하며, 정보주체의 동의, 법률의 특별한 규정 등 「개인정보 보호법」 제17조 및 제18조에 해당하는 경우 외에는 개인정보를 제3자에게 제공하지 않습니다.\n\n회사는 현재 정보주체의 개인정보를 제3자에게 제공하고 있지 않습니다."},{"title":"제5조 (개인정보 처리의 위탁)","body":"회사는 원활한 서비스 제공을 위하여 다음과 같이 개인정보 처리업무를 위탁하고 있습니다.\n\n· Supabase Inc.: 데이터베이스, 인증, 스토리지 운영 / 위탁 기간은 위탁계약 종료 시 또는 회원 탈퇴 시까지 / 처리 국가: 대한민국(서울 리전)\n· 네이버클라우드 주식회사(Naver Cloud Platform): 지도 타일 및 지도 관련 기능 제공 / 처리 국가: 대한민국\n· Google LLC (Google Identity Services): Google 계정 로그인 시 발급되는 인증 토큰의 검증을 통한 본인 인증 / 처리 국가: 미국\n· Google LLC (Firebase Cloud Messaging): Android 기기 대상 푸시 알림 발송을 위한 푸시 토큰 처리 및 메시지 전송 / 처리 국가: 미국\n· Apple Inc. (Apple Push Notification Service): iOS 기기 대상 푸시 알림 발송을 위한 푸시 토큰 처리 및 메시지 전송 / 처리 국가: 미국\n· 주식회사 카카오(Kakao Corp.): Kakao 계정 로그인을 통한 본인 인증 / 처리 국가: 대한민국\n· Apple Inc. (Sign in with Apple): Apple 계정 로그인을 통한 본인 인증 / 처리 국가: 미국\n\n· Functional Software Inc. (Sentry): 앱 비정상 종료 시점의 스택 트레이스, 에러 메시지, 발생 환경 수집·집계(서비스 안정성 개선 목적) / 처리 국가: 미국\n\n회사는 맞춤형 광고 목적의 업무를 외부에 위탁하고 있지 않습니다. 향후 이러한 위탁이 발생할 경우 본 처리방침을 통해 사전에 공지합니다.\n\n회사는 위탁계약 체결 시 「개인정보 보호법」 제26조에 따라 위탁업무 수행목적 외 개인정보 처리 금지, 기술적·관리적 보호조치, 재위탁 제한, 수탁자에 대한 관리·감독, 손해배상 등 책임에 관한 사항을 문서에 명시하고, 수탁자가 개인정보를 안전하게 처리하는지를 감독합니다."},{"title":"제6조 (개인정보의 파기 절차 및 방법)","body":"회사는 개인정보 보유기간의 경과, 처리목적 달성 등 개인정보가 불필요하게 되었을 때에는 지체 없이 해당 개인정보를 파기합니다.\n\n파기 절차: 파기 사유가 발생한 개인정보는 개인정보 보호책임자의 확인을 거쳐 파기합니다.\n\n파기 방법: 전자적 파일 형태의 정보는 복구 및 재생이 불가능한 방법으로 영구 삭제합니다. 기기에만 저장된 정보는 회원 탈퇴 또는 앱 삭제 시 해당 기기에서 삭제됩니다. 프로필 사진은 회원 탈퇴 시 스토리지에서 즉시 삭제합니다.\n\n닉네임 선점 기록 및 알림 이력은 회원 탈퇴 시 지체 없이 파기합니다. 제보 데이터는 개인 식별이 불가능하도록 익명화 처리합니다."},{"title":"제7조 (정보주체와 법정대리인의 권리·의무 및 행사 방법)","body":"정보주체는 회사에 대하여 언제든지 개인정보 열람, 정정, 삭제, 처리정지 및 전송요구의 권리를 행사할 수 있습니다.\n\n권리 행사는 「개인정보 보호법」 시행령 제41조 제1항에 따라 서면, 전자우편 등을 통하여 하실 수 있으며, 회사는 이에 대하여 지체 없이 조치합니다. 정보주체가 개인정보의 오류 등에 대한 정정 또는 삭제를 요구한 경우, 회사는 정정 또는 삭제를 완료할 때까지 해당 개인정보를 이용하거나 제공하지 않습니다.\n\n서비스 특성상 회원의 프로필 등 대부분의 개인정보는 회원 본인의 기기에 저장되므로, 정보주체는 서비스 내 프로필 및 설정 화면에서 직접 해당 정보를 열람·정정·삭제할 수 있습니다. 서버에 저장된 정보(닉네임 문자열, 프로필 사진, 알림 이력 등)에 대한 권리 행사는 아래 연락처로 요청하실 수 있습니다.\n\n· 이메일: cripo2357@gmail.com\n· 서비스 내 설정 메뉴(프로필 관리, 회원 탈퇴 등)\n\n회사는 만 14세 미만 아동의 가입을 받지 않으므로 통상적으로 법정대리인의 권리 대리 행사가 발생하지 않으나, 관련 사유가 확인되는 경우 법정대리인은 아동의 개인정보에 대한 열람, 정정, 삭제, 처리정지를 요구할 수 있습니다.\n\n회사는 권리 행사 요청자가 본인 또는 정당한 대리인인지 확인하기 위하여 관련 자료의 제출을 요청할 수 있습니다. 대리인을 통하여 권리를 행사하는 경우 위임장 등 대리권을 증명하는 서류를 제출하여야 합니다.\n\n전송요구권 안내: 정보주체는 「개인정보 보호법」 제35조의2에 따라 본인의 개인정보를 본인 또는 다른 개인정보처리자 등에게 전송하도록 요구할 수 있습니다. 현재 회사는 별도의 자동화된 전송 시스템을 운영하고 있지 않으며, 전송요구가 있는 경우 위 연락처를 통해 관련 법령이 정하는 범위에서 처리합니다. 향후 전송 방법, 전송 현황 및 내역 확인 방법을 별도로 마련하는 경우 본 처리방침을 통해 안내합니다."},{"title":"제8조 (개인정보 자동 수집 장치의 설치·운영 및 거부)","body":"회사는 이용자의 행태정보를 수집하기 위한 쿠키, 웹 비콘, 광고식별자 등의 자동 수집 장치를 사용하지 않으며, 맞춤형 광고를 위한 행태정보를 처리하지 않습니다.\n\n다만 서비스의 안정적 운영과 품질 개선을 위하여 §2(처리하는 개인정보의 항목)에서 안내한 크래시·에러 리포팅(Sentry — Functional Software Inc., 미국)이 자동으로 동작합니다. 개인 식별자(닉네임/이메일/사용자 ID/GPS 좌표)는 전송되지 않으며, Sentry 의 경우 로그인 사용자의 친구 코드(6자 무작위 문자열)만 함께 전송됩니다.\n\n이용자가 크래시 리포팅을 수신·전송하지 않으려는 경우, 앱을 사용하지 않거나 삭제함으로써 자동 수집을 중단할 수 있습니다. 단, 개별 항목 단위의 비활성 토글은 현재 제공되지 않으며, 향후 도입 시 본 처리방침을 통해 안내합니다.\n\n서비스 제공 시점에 기기 위치정보가 일시적으로 이용될 수 있으나, 회사는 이를 저장하거나 로그로 남기지 않습니다. 자세한 내용은 위치기반서비스 이용약관에서 안내합니다.\n\n회사가 향후 추가적인 자동 수집 도구를 도입하거나 기존 도구의 수집 항목·목적을 변경하는 경우, 사전에 본 처리방침을 개정하여 수집 항목, 목적, 보유 기간 및 거부 방법을 안내합니다."},{"title":"제9조 (개인정보의 안전성 확보 조치)","body":"회사는 개인정보의 안전성 확보를 위하여 다음과 같은 조치를 취하고 있습니다.\n\n· 관리적 조치: 개인정보 취급 인원의 최소화, 처리 목적 외 이용 금지 원칙의 운영\n· 기술적 조치: 개인정보처리시스템에 대한 접근권한 관리, 데이터 접근 통제(행 수준 보안 정책 적용), 전송 구간 암호화, 인증 토큰의 안전한 관리\n· 구조적 조치: 회원의 프로필 등 개인정보 대부분을 회사 서버로 전송하지 않고 이용자 기기 내부에만 저장하여 서버 측 개인정보 처리량을 최소화\n· 물리적 조치: 데이터가 저장되는 인프라(국내 서울 리전)의 물리적 보안은 수탁자의 보안 체계에 따라 관리·감독"},{"title":"제10조 (개인정보 보호책임자 및 고충처리)","body":"회사는 개인정보 처리에 관한 업무를 총괄해서 책임지고, 개인정보 처리와 관련한 정보주체의 불만처리 및 피해구제를 위하여 아래와 같이 개인정보 보호책임자를 지정하고 있습니다.\n\n[개인정보 보호책임자]\n· 성명: 김은호\n· 직책: 개인정보 보호책임자\n· 이메일: cripo2357@gmail.com\n\n고충처리는 위 개인정보 보호책임자가 함께 담당합니다. 정보주체는 서비스 이용 중 발생한 개인정보 관련 문의, 불만, 피해구제 등에 관한 사항을 위 연락처로 문의할 수 있으며, 회사는 지체 없이 답변 및 처리합니다."},{"title":"제11조 (만 14세 미만 아동의 개인정보 처리)","body":"회사는 만 14세 미만 아동의 회원 가입을 받지 않으며, 회원 가입 시 만 14세 이상임을 확인합니다. 따라서 회사는 만 14세 미만 아동의 개인정보를 수집·이용하지 않습니다. 만 14세 미만임이 확인된 경우 회사는 해당 정보를 지체 없이 파기합니다."},{"title":"제12조 (개인정보의 국외 이전)","body":"회원 데이터가 저장되는 인프라는 국내(서울 리전)에 위치하므로, 회사가 저장·관리하는 개인정보의 국외 이전은 발생하지 않습니다.\n\n다만 이용자가 Google 또는 Apple 계정으로 로그인하는 경우, 본인 인증 과정에서 각각 Google LLC(미국) 또는 Apple Inc.(미국)를 통한 인증 토큰 검증이 이루어집니다. 이는 이용자가 선택한 로그인 수단에 한하여 인증 목적으로만 처리되며, Kakao 계정 로그인을 이용하는 경우 해당 처리는 발생하지 않습니다.\n\nOS 푸시 알림 발송을 위하여 푸시 토큰은 다음과 같이 처리됩니다. Android 기기의 경우 Google LLC가 운영하는 Firebase Cloud Messaging(미국), iOS 기기의 경우 Apple Inc.가 운영하는 Apple Push Notification Service(미국)에 전송되며, 푸시 알림 발송 목적으로만 이용됩니다. 이용자가 OS 푸시 알림 권한을 거부하거나 회원 탈퇴를 하는 경우 푸시 토큰은 즉시 폐기되며, 해당 시점 이후 국외 이전은 발생하지 않습니다.\n\n또한 서비스의 안정적 운영과 품질 개선을 위하여 §2 에서 안내한 다음 항목이 국외로 이전됩니다.\n\n· 크래시 및 에러 리포팅: Functional Software Inc.가 운영하는 Sentry(미국)로 스택 트레이스, 에러 메시지, 발생 환경 및 로그인 사용자의 친구 코드(해당하는 경우)가 전송됩니다.\n\n위 항목들은 개인 식별자(닉네임/이메일/사용자 ID/GPS 좌표)를 포함하지 않습니다. 이용자가 이 자동 수집을 차단하려면 앱을 사용하지 않거나 삭제하셔야 합니다.\n\n회사가 향후 추가로 개인정보를 국외로 이전하게 되는 경우, 「개인정보 보호법」 제28조의8에 따라 이전되는 항목, 이전 국가·시기·방법, 이전받는 자, 이용 목적 및 보유 기간 등을 사전에 안내하고 필요한 경우 별도의 동의를 받습니다."},{"title":"제13조 (개인정보 처리방침의 변경)","body":"본 개인정보 처리방침은 시행일로부터 적용되며, 법령 및 방침에 따른 변경 내용의 추가, 삭제 및 정정이 있는 경우에는 변경사항의 시행 7일 전부터 서비스 내 공지사항을 통하여 고지합니다. 정보주체의 권리에 중대한 영향을 미치는 변경의 경우 최소 30일 전부터 고지합니다.\n\n[개정 이력]\n· 2026년 5월 28일: 최초 제정"},{"title":"정보주체의 권익침해 구제 방법","body":"정보주체는 개인정보 침해로 인한 구제를 받기 위하여 아래 기관에 분쟁 해결이나 상담 등을 신청할 수 있습니다.\n\n· 개인정보분쟁조정위원회: 국번 없이 1833-6972 (www.kopico.go.kr)\n· 개인정보침해신고센터: 국번 없이 118 (privacy.kisa.or.kr)\n· 대검찰청 사이버수사과: 국번 없이 1301 (www.spo.go.kr)\n· 경찰청 사이버수사국: 국번 없이 182 (ecrm.cyber.go.kr)"},{"title":"사업주·대표자의 책임","body":"회사의 사업주 및 대표자는 「개인정보 보호법」에 따라 개인정보 보호에 관한 최종 책임을 부담하며, 개인정보의 안전한 처리를 위하여 필요한 조치를 이행합니다."},{"title":"사업자 정보","body":"· 상호: CRIPO\n· 대표자: 김은호\n· 사업자등록번호: 379-13-02772\n· 사업장 주소: 경기도 화성시 병점구 효행로 1068, 604호\n· 이메일: cripo2357@gmail.com"},{"title":"부칙","body":"이 개인정보 처리방침은 2026년 5월 28일부터 시행합니다."}]}$tjson$::jsonb, false, false, true)
on conflict (type, version) do update set
  content=excluded.content, effective_date=excluded.effective_date,
  is_required=excluded.is_required, requires_consent=excluded.requires_consent, is_active=true;

-- location
update public.terms set is_active=false where type='location' and version<>'1.0.3';
insert into public.terms (type, version, effective_date, content, is_required, requires_consent, is_active)
values ('location', '1.0.3', '2026-05-28', $tjson${"title":"위치기반서비스 이용약관","version":"v1.0.3","effectiveDate":"2026년 5월 28일","sections":[{"title":"들어가며","body":"CRIPO(이하 \"회사\")는 Pool's day(풀스데이) 서비스에서 이용자의 위치정보를 어떻게 다루는지 투명하게 안내드립니다. 핵심부터 말씀드리면, 회사는 이용자의 기기 위치를 저장하지 않고 그 순간에만 사용한 뒤 즉시 폐기합니다."},{"title":"제1조 (목적)","body":"이 약관은 회사가 제공하는 위치기반서비스와 관련하여 회사와 개인위치정보주체 간의 권리·의무 및 책임사항, 기타 필요한 사항을 규정함을 목적으로 합니다."},{"title":"제2조 (약관 외 준칙)","body":"이 약관에 명시되지 않은 사항은 「위치정보의 보호 및 이용 등에 관한 법률」, 「개인정보 보호법」, 기타 관계 법령 및 회사가 정한 서비스 이용약관, 개인정보 처리방침에 따릅니다."},{"title":"제3조 (서비스의 내용)","body":"회사는 개인위치정보를 이용하여 다음의 위치기반서비스를 제공합니다.\n\n· 현재 위치를 기준으로 한 지도 화면 이동(내 위치 보기)\n· 현재 위치와 가까운 순서로 수영장 목록 정렬\n· 근거리 자유수영 수영장 추천\n\n회사는 위 목적 범위에서만 개인위치정보를 이용하며, 이용자의 이동 경로 추적, 위치 이력 분석 등은 수행하지 않습니다."},{"title":"제4조 (개인위치정보의 수집·이용·제공)","body":"수집 방법: 회사는 이용자가 위 서비스 기능을 사용하는 시점에 운영체제(OS)의 위치 권한을 통하여 기기 위치(GPS 기반 위경도)를 일시적으로 확인합니다. 회사는 \"앱 사용 중에만\" 권한을 요청하며 \"항상 허용\" 권한을 요구하지 않습니다.\n\n이용 방법: 확인된 위치정보는 해당 기능 제공을 위해 이용자 기기 내에서 즉시 처리되며, 회사 서버로 전송되지 않습니다.\n\n보유 및 파기: 회사는 개인위치정보를 저장하지 않습니다. 위치정보는 기능 사용 직후 또는 다른 화면으로 이동·앱 종료 시 즉시 휘발되며, 별도의 보유 기간이 존재하지 않습니다(보유 기간 0).\n\n이용·제공사실 확인자료: 회사는 개인위치정보를 저장하지 않으므로 위치정보의 이용·제공사실 확인자료를 생성하거나 보관하지 않습니다.\n\n제3자 제공: 회사는 개인위치정보를 제3자에게 제공하지 않습니다. 다만 지도 화면 표시를 위하여 이용자가 현재 보고 있는 지도 화면의 중심 좌표(이는 지도 영역을 나타내는 좌표이며, 이용자의 실제 기기 위치와는 다릅니다)가 지도 제공 사업자(네이버클라우드 주식회사, 대한민국)에 전달될 수 있으며, 이는 지도 화면 표시 목적으로만 이용됩니다."},{"title":"제5조 (개인위치정보주체의 권리)","body":"개인위치정보주체는 위치정보 이용에 대한 동의의 전부 또는 일부를 언제든지 철회할 수 있습니다. 동의 철회는 기기 운영체제의 위치 권한 설정에서 본 서비스의 위치 권한을 해제하는 방법으로 할 수 있습니다.\n\n위치 권한을 허용하지 않거나 동의를 철회하더라도 서비스의 다른 기능은 정상적으로 이용할 수 있습니다. 다만 \"내 위치 보기\", 거리순 정렬, 근거리 추천 기능은 이용이 제한됩니다.\n\n개인위치정보주체는 「위치정보의 보호 및 이용 등에 관한 법률」 제24조에 따라 개인위치정보의 이용·제공사실 확인자료에 대한 열람·고지를 요구할 수 있습니다. 다만 회사는 개인위치정보를 저장하지 않고 이용·제공사실 확인자료를 생성·보관하지 않으므로, 제공할 수 있는 자료가 존재하지 않음을 안내드립니다."},{"title":"제6조 (법정대리인의 권리 및 아동의 보호)","body":"회사는 만 14세 미만 아동의 회원 가입을 받지 않으며, 만 8세 이하의 아동 등을 대상으로 한 별도의 위치정보 보호 의무자 지정 서비스를 제공하지 않습니다.\n\n회사가 14세 미만 아동의 개인위치정보를 처리하게 되는 경우에는 「위치정보의 보호 및 이용 등에 관한 법률」 제25조에 따라 그 법정대리인의 동의를 받는 등 법령이 정하는 절차를 따릅니다."},{"title":"제7조 (위치정보 관리책임자)","body":"회사는 개인위치정보를 적절히 관리·보호하고 개인위치정보주체의 불만을 원활히 처리하기 위하여 다음과 같이 위치정보 관리책임자를 지정합니다.\n\n· 성명: 김은호\n· 직책: 위치정보 관리책임자\n· 이메일: cripo2357@gmail.com"},{"title":"제8조 (손해배상 및 면책)","body":"회사가 「위치정보의 보호 및 이용 등에 관한 법률」 제15조부터 제26조까지의 규정을 위반한 행위로 개인위치정보주체에게 손해가 발생한 경우, 개인위치정보주체는 회사에 대하여 손해배상을 청구할 수 있습니다. 이 경우 회사는 고의·과실이 없음을 입증하지 못하면 책임을 면할 수 없습니다.\n\n회사는 천재지변, 불가항력, 이용자의 기기 또는 운영체제 설정 문제, 이용자의 귀책사유로 인하여 위치기반서비스가 제공되지 못한 경우 그에 대한 책임을 지지 않습니다."},{"title":"제9조 (분쟁의 조정 및 준거법)","body":"회사 또는 개인위치정보주체는 위치정보와 관련된 분쟁에 대하여 당사자 간 협의가 이루어지지 아니하거나 협의를 할 수 없는 경우 「개인정보 보호법」에 따른 개인정보분쟁조정위원회 또는 「방송통신위원회의 설치 및 운영에 관한 법률」에 따른 방송통신위원회에 재정 또는 분쟁의 조정을 신청할 수 있습니다.\n\n이 약관과 관련된 분쟁에 관하여는 대한민국 법을 준거법으로 하며, 소송은 「민사소송법」에 따른 관할 법원을 제1심 관할 법원으로 합니다."},{"title":"사업자 정보","body":"· 상호: CRIPO\n· 대표자: 김은호\n· 사업자등록번호: 379-13-02772\n· 사업장 주소: 경기도 화성시 병점구 효행로 1068, 604호\n· 이메일: cripo2357@gmail.com"},{"title":"부칙","body":"이 위치기반서비스 이용약관은 2026년 5월 28일부터 시행합니다."}]}$tjson$::jsonb, true, true, true)
on conflict (type, version) do update set
  content=excluded.content, effective_date=excluded.effective_date,
  is_required=excluded.is_required, requires_consent=excluded.requires_consent, is_active=true;

-- marketing
update public.terms set is_active=false where type='marketing' and version<>'1.0.3';
insert into public.terms (type, version, effective_date, content, is_required, requires_consent, is_active)
values ('marketing', '1.0.3', '2026-05-28', $tjson${"title":"마케팅 정보 수신 동의","version":"v1.0.3","effectiveDate":"2026년 5월 28일","sections":[{"title":"들어가며","body":"CRIPO(이하 \"회사\")는 Pool's day(풀스데이) 이용자에게 도움이 될 만한 소식을 전해드리고자 합니다. 본 동의는 선택 사항이며, 동의하지 않으셔도 서비스의 모든 기능을 동일하게 이용하실 수 있습니다. 같은 물에서 헤엄치는 동지에게 가끔 반가운 소식을 전하는 정도라고 생각해 주세요."},{"title":"1. 수신 동의 목적","body":"회사는 다음의 목적으로 광고성 정보를 전송하기 위하여 이용자의 동의를 받습니다.\n\n· 신규 기능 및 서비스 개선 사항 안내\n· 이벤트, 혜택, 설문 등 참여 기회 안내\n· 이용자 맞춤 정보 및 추천 안내"},{"title":"2. 전송 방식","body":"광고성 정보는 인앱 알림, 운영체제(OS) 푸시 알림 또는 이메일을 통하여 전송될 수 있습니다.\n\n시행일 기준 회사는 마케팅 정보 발송을 시작하지 않은 상태입니다. 본 동의는 마케팅 발송 시작 시점에 발송 대상을 확인하기 위해 미리 받아 두는 것이며, 실제 발송이 시작되는 시점에 회사는 발송 채널, 발송자, 광고성 정보의 유형 및 수신 거부 방법을 서비스 내 공지사항 또는 인앱 알림을 통하여 사전에 안내합니다. 안내 시점에 이용자는 본 동의를 유지하거나 철회할 수 있습니다."},{"title":"3. 수집·이용 항목","body":"마케팅 정보 전송을 위하여 회사는 회원 가입 시 이미 수집한 닉네임, 친구코드, 이메일 등 식별·연락 정보를 발송 대상 확인 목적으로 이용합니다. 본 동의를 위하여 추가로 수집하는 별도의 개인정보는 없습니다."},{"title":"4. 보유·이용 기간","body":"마케팅 수신 동의에 따른 개인정보 이용은 동의를 철회하거나 회원에서 탈퇴할 때까지 유지되며, 동의 철회 또는 회원 탈퇴 시 해당 목적의 이용을 중단합니다."},{"title":"5. 동의 철회 방법","body":"이용자는 언제든지 마케팅 정보 수신 동의를 철회할 수 있습니다.\n\n· 서비스 내 설정 메뉴의 알림 설정에서 수신 거부\n· 이메일(cripo2357@gmail.com)로 수신 거부 요청\n· 발송되는 광고성 정보 내에 안내되는 수신 거부 방법(발송 시작 이후 제공)\n\n동의를 철회하시면 그 이후의 광고성 정보 전송이 중단됩니다. 단, 서비스 운영에 필요한 공지사항 등 의무적·거래적 안내는 마케팅 수신 동의 여부와 관계없이 제공될 수 있습니다."},{"title":"6. 동의 거부 권리 및 불이익 없음","body":"이용자는 본 마케팅 정보 수신 동의를 거부할 권리가 있으며, 동의를 거부하거나 추후 철회하더라도 서비스 이용에 어떠한 불이익도 없습니다."},{"title":"동의","body":"본인은 위 내용을 충분히 읽고 이해하였으며, 마케팅 정보 수신에 동의합니다.\n\n(선택) 마케팅 정보 수신에 동의합니다."},{"title":"부칙","body":"이 마케팅 정보 수신 동의서는 2026년 5월 28일부터 시행합니다.\n\n좋은 소식만 골라서 전할게요. — Pool's day 드림"}]}$tjson$::jsonb, false, true, true)
on conflict (type, version) do update set
  content=excluded.content, effective_date=excluded.effective_date,
  is_required=excluded.is_required, requires_consent=excluded.requires_consent, is_active=true;
